package com.example.proyectolp.repository;
import com.example.proyectolp.model.CreditEntry; import com.example.proyectolp.service.SupabaseService; import java.util.*;
public class CreditLedgerRepository { private final SupabaseService db; public CreditLedgerRepository(SupabaseService d){db=d;} public List<CreditEntry> list()throws Exception{List<CreditEntry> all=new ArrayList<>();int offset=0;while(true){List<CreditEntry> page=db.getList("credit_ledger?select=*&order=created_at.desc,id.desc&limit=1000&offset="+offset,CreditEntry.class);all.addAll(page);if(page.size()<1000)return all;offset+=1000;}} public int balance()throws Exception{return list().stream().mapToInt(e->e.credits).sum();} public boolean insert(String type,int credits,String description,String key)throws Exception{return !db.insertIgnore("credit_ledger?on_conflict=user_id,dedupe_key",Map.of("entry_type",type,"credits",credits,"description",description,"dedupe_key",key),CreditEntry.class).isEmpty();} }
